@page "/apply"
@rendermode InteractiveServer
@using sv_66738855f5a642569a883e5723f660a3.Models
@using sv_66738855f5a642569a883e5723f660a3.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h1 class="mb-4">Job Application</h1>

    @* ── Step Indicator Bar ── *@
    <nav class="d-flex justify-content-between mb-4 position-relative">
        <div class="position-absolute" style="top: 20px; left: 40px; right: 40px; height: 2px; background: #dee2e6; z-index: 0;"></div>
        @for (int i = 0; i < StepLabels.Length; i++)
        {
            var step = i + 1;
            var isCompleted = step < _currentStep;
            var isCurrent = step == _currentStep;
            var isFuture = step > _currentStep;

            <div class="text-center position-relative" style="z-index: 1; flex: 1;">
                <button type="button"
                        class="btn rounded-circle d-inline-flex align-items-center justify-content-center mb-1 @(isCurrent ? "btn-primary" : isCompleted ? "btn-success" : "btn-outline-secondary")"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@(isFuture || _submitted)"
                        @onclick="() => GoToStep(step)">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        @step
                    }
                </button>
                <div class="small @(isFuture ? "text-muted" : "")">@StepLabels[i]</div>
            </div>
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    @if (_submitted)
    {
        @* ── Confirmation ── *@
        <div class="text-center py-5">
            <div class="text-success mb-3" style="font-size: 3rem;">&#10003;</div>
            <h2>Application Submitted!</h2>
            <p class="lead">Your application ID is <strong>@_applicationId</strong></p>
            <p class="text-muted">We'll review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        @* ── Step 1: Personal Info ── *@
        @if (_currentStep == 1)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">Personal Information</h4>

                    <div class="mb-3">
                        <label class="form-label">Full Name <span class="text-danger">*</span></label>
                        <input class="form-control" @bind="_fullName" placeholder="John Doe" />
                    </div>

                    <div class="mb-3">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control" @bind="_email" placeholder="john@example.com" />
                    </div>

                    <div class="mb-3">
                        <label class="form-label">Phone <span class="text-danger">*</span></label>
                        <input type="tel" class="form-control" @bind="_phone" placeholder="(555) 123-4567" />
                    </div>

                    <div class="mb-3">
                        <label class="form-label">Address <span class="text-danger">*</span></label>
                        <textarea class="form-control" rows="2" @bind="_address" placeholder="123 Main St, City, State ZIP"></textarea>
                    </div>

                    <div class="d-flex justify-content-end">
                        <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                            @if (_isValidating)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                                <span>Validating…</span>
                            }
                            else
                            {
                                <span>Next &rarr;</span>
                            }
                        </button>
                    </div>
                </div>
            </div>
        }

        @* ── Step 2: Work History ── *@
        @if (_currentStep == 2)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">Work History</h4>

                    @for (int i = 0; i < _workEntries.Count; i++)
                    {
                        var index = i;
                        var entry = _workEntries[index];

                        <div class="border rounded p-3 mb-3">
                            <div class="d-flex justify-content-between align-items-center mb-2">
                                <h6 class="mb-0">Position @(index + 1)</h6>
                                @if (_workEntries.Count > 1)
                                {
                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                                }
                            </div>

                            <div class="row mb-2">
                                <div class="col-md-6">
                                    <label class="form-label">Company <span class="text-danger">*</span></label>
                                    <input class="form-control" value="@entry.Company" @onchange="e => UpdateWorkEntry(index, entry with { Company = (string?)e.Value ?? string.Empty })" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                    <input class="form-control" value="@entry.Title" @onchange="e => UpdateWorkEntry(index, entry with { Title = (string?)e.Value ?? string.Empty })" />
                                </div>
                            </div>

                            <div class="row mb-2">
                                <div class="col-md-4">
                                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                    <input type="date" class="form-control" value="@FormatDate(entry.StartDate)" @onchange="e => UpdateWorkEntry(index, entry with { StartDate = ParseDate(e.Value) })" />
                                </div>
                                <div class="col-md-4">
                                    <label class="form-label">End Date</label>
                                    <input type="date" class="form-control" value="@FormatDate(entry.EndDate)" disabled="@entry.IsCurrent"
                                           @onchange="e => UpdateWorkEntry(index, entry with { EndDate = ParseNullableDate(e.Value) })" />
                                </div>
                                <div class="col-md-4 d-flex align-items-end">
                                    <div class="form-check mb-2">
                                        <input type="checkbox" class="form-check-input" id="@($"current-{index}")" checked="@entry.IsCurrent"
                                               @onchange="e => UpdateWorkEntry(index, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : entry.EndDate })" />
                                        <label class="form-check-label" for="@($"current-{index}")">Currently working here</label>
                                    </div>
                                </div>
                            </div>

                            <div class="mb-0">
                                <label class="form-label">Description</label>
                                <textarea class="form-control" rows="2" value="@entry.Description"
                                          @onchange="e => UpdateWorkEntry(index, entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
                            </div>
                        </div>
                    }

                    <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-outline-secondary" @onclick="() => GoToStep(1)">&larr; Back</button>
                        <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next &rarr;</button>
                    </div>
                </div>
            </div>
        }

        @* ── Step 3: References ── *@
        @if (_currentStep == 3)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">References</h4>

                    @for (int i = 0; i < _references.Count; i++)
                    {
                        var index = i;
                        var refEntry = _references[index];

                        <div class="border rounded p-3 mb-3">
                            <div class="d-flex justify-content-between align-items-center mb-2">
                                <h6 class="mb-0">Reference @(index + 1)</h6>
                                @if (_references.Count > 2)
                                {
                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                                }
                            </div>

                            <div class="row mb-2">
                                <div class="col-md-6">
                                    <label class="form-label">Name <span class="text-danger">*</span></label>
                                    <input class="form-control" value="@refEntry.Name" @onchange="e => UpdateReference(index, refEntry with { Name = (string?)e.Value ?? string.Empty })" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                    <input class="form-control" value="@refEntry.Relationship" @onchange="e => UpdateReference(index, refEntry with { Relationship = (string?)e.Value ?? string.Empty })" />
                                </div>
                            </div>

                            <div class="row mb-0">
                                <div class="col-md-6">
                                    <label class="form-label">Email <span class="text-danger">*</span></label>
                                    <input type="email" class="form-control" value="@refEntry.Email" @onchange="e => UpdateReference(index, refEntry with { Email = (string?)e.Value ?? string.Empty })" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                                    <input type="tel" class="form-control" value="@refEntry.Phone" @onchange="e => UpdateReference(index, refEntry with { Phone = (string?)e.Value ?? string.Empty })" />
                                </div>
                            </div>
                        </div>
                    }

                    @if (_references.Count < 3)
                    {
                        <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddReference">+ Add Reference</button>
                    }

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-outline-secondary" @onclick="() => GoToStep(2)">&larr; Back</button>
                        <button class="btn btn-primary" @onclick="NextFromReferences">Next &rarr;</button>
                    </div>
                </div>
            </div>
        }

        @* ── Step 4: Cover Letter ── *@
        @if (_currentStep == 4)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">Cover Letter</h4>

                    <div class="mb-2">
                        <textarea class="form-control" rows="10" maxlength="2000" @bind="_coverLetter"
                                  placeholder="Write your cover letter here…"></textarea>
                    </div>
                    <div class="text-muted small mb-3">@(_coverLetter?.Length ?? 0) / 2000 characters</div>

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-outline-secondary" @onclick="() => GoToStep(3)">&larr; Back</button>
                        <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next &rarr;</button>
                    </div>
                </div>
            </div>
        }

        @* ── Step 5: Review & Submit ── *@
        @if (_currentStep == 5)
        {
            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">Personal Information</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">Work History</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    @foreach (var entry in _workEntries)
                    {
                        <div class="border-start border-3 ps-3 mb-2">
                            <strong>@entry.Title</strong> at @entry.Company<br />
                            <span class="text-muted small">
                                @entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                            </span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mb-0 mt-1 small">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">References</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    @foreach (var r in _references)
                    {
                        <div class="mb-2">
                            <strong>@r.Name</strong> (@r.Relationship)<br />
                            <span class="small text-muted">@r.Email &middot; @r.Phone</span>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">Cover Letter</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(4)">Edit</button>
                    </div>
                    <p class="mb-0" style="white-space: pre-wrap;">@_coverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-outline-secondary" @onclick="() => GoToStep(4)">&larr; Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                    @if (_isSubmitting)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                        <span>Submitting…</span>
                    }
                    else
                    {
                        <span>Submit Application</span>
                    }
                </button>
            </div>
        }
    }
</div>

